def get_flatten_fields(self, field_types: dict) -> dict:
    """Resolve flattened wire keys and validate their ownership."""
    result = {}
    owners = {}
    for fname, ftype in field_types.items():
        metadata = self.metadatas.get(fname, {})
        if not metadata.get("flatten"):
            alias = self.__get_field_alias(fname, ftype, metadata, self.get_config())
            for key in {fname, alias} - {None}:
                owners.setdefault(key, set()).add(fname)
            continue
        typ = self.get_real_type(fname, ftype)
        while is_annotated(typ):
            typ = get_args(typ)[0]
        optional = is_optional(typ)
        if optional:
            typ = next(t for t in get_args(typ) if t is not NoneType)
        origin = get_type_origin(typ)
        if not is_dataclass(origin):
            raise ValueError(f"Flattened field {fname!r} must be a dataclass")
        prefix = metadata.get("flatten_prefix")
        rename = metadata.get("flatten_rename")
        if prefix is not None and prefix is not False and rename is not None:
            raise ValueError("flatten_prefix and flatten_rename are mutually exclusive")
        if prefix is True:
            prefix = fname + "_"
        elif prefix is None or prefix is False:
            prefix = ""
        elif not isinstance(prefix, str):
            raise ValueError("flatten_prefix must be a string or True")
        if rename is not None and (not isinstance(rename, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in rename.items())):
            raise ValueError("flatten_rename must map field names to strings")
        rename = rename or {}
        child = CodeBuilder(origin, get_args(typ), dialect=self.dialect, default_dialect=self.default_dialect)
        child.reset()
        child_types = child.get_field_types(include_extras=True)
        child_flat = child.get_flatten_fields(child_types)
        child_keys = {}
        for name, child_type in child_types.items():
            if name in child_flat:
                for key in child_flat[name][0]:
                    child_keys[key] = {key}
            else:
                alias = child.__get_field_alias(name, child_type, child.metadatas.get(name, {}), child.get_config())
                child_keys[name] = {name, alias} - {None}
        if set(rename) - set(child_keys):
            raise ValueError(f"Invalid flatten_rename keys for {fname!r}")
        mapping = {}
        for name, keys in child_keys.items():
            for key in keys:
                target = rename.get(name, prefix + key)
                if target in mapping.values() and mapping.get(key) != target:
                    raise ValueError(f"Duplicate flattened key {target!r}")
                mapping[key] = target
                owners.setdefault(target, set()).add(fname)
        result[fname] = (mapping, optional)
    if result:
        collisions = [key for key, fields in owners.items() if len(fields) > 1]
        if collisions:
            raise ValueError(f"Flattened field key collision: {collisions!r}")
    return result

